head.b:skin:
/* Creactivos Audiovisual · tema generado a partir del sitio nuevo */
html{-webkit-text-size-adjust:100%}
body{margin:0;background:#fff;color:#000;font:17px/1.6 Geist,system-ui,-apple-system,'Segoe UI',Arial,sans-serif}
.cr *{box-sizing:border-box}
.cr a{color:#000}
.cr img{max-width:100%}
.cr h1,.cr h2,.cr h3,.cr h4{color:#000;line-height:1.2;margin:0 0 .5em;font-weight:700}
.cr h1{font-size:2.6em}.cr h2{font-size:1.9em}.cr h3{font-size:1.35em}.cr h4{font-size:1.1em}
.cr p{margin:0 0 .9em}
.cr ul{margin:0 0 1em;padding-left:1.3em}
.cr-sr{position:absolute;width:1px;height:1px;overflow:hidden;clip:rect(0 0 0 0);white-space:nowrap}
.cr-wrap{max-width:1000px;margin:0 auto;padding:0 16px}
.cr-head{border-bottom:4px solid #E4162B}
.cr-head .cr-wrap{display:flex;flex-wrap:wrap;align-items:center;justify-content:space-between;gap:12px;padding-top:12px;padding-bottom:12px}
.cr-logo img{display:block;width:140px;height:auto}
.cr-nav{display:flex;flex-wrap:wrap;align-items:center;gap:0 24px;font-size:1.1em;font-weight:700}
.cr-nav>div{position:relative}
.cr-nav a{text-decoration:none;display:block;padding:8px 0}
.cr-nav a:hover{text-decoration:underline}
.cr-sub{visibility:hidden;position:absolute;left:0;top:100%;z-index:20;min-width:200px;background:#fff;border:1px solid #d4d4d8;border-radius:6px;box-shadow:0 8px 20px rgba(0,0,0,.12);padding:4px 0;font-weight:400;font-size:.95em}
.cr-nav>div:hover .cr-sub,.cr-nav>div:focus-within .cr-sub{visibility:visible}
.cr-sub a{padding:8px 16px}.cr-sub a:hover{background:#f4f4f5;text-decoration:none}
.cr-main{padding-top:40px;padding-bottom:40px}
.cr section{margin:0 0 3.5em}
.cr-eyebrow{font-size:.8em;letter-spacing:.12em;text-transform:uppercase;font-weight:700;margin:0 0 .6em}
.cr-pills{display:flex;flex-wrap:wrap;gap:.5em;list-style:none;padding:0}
.cr-pills li{border:2px solid #000;border-radius:999px;padding:.1em .9em;font-size:.9em;font-weight:700}
.cr-btn{display:inline-block;background:#E4162B;color:#000!important;font-weight:700;padding:.5em 1.2em;border-radius:4px;text-decoration:none;margin:0 .5em .5em 0}
.cr-btn.alt{background:#fff;border:2px solid #000}
.cr-grid2{display:grid;grid-template-columns:repeat(2,1fr);gap:1.2em}
.cr-card{border:1px solid #d4d4d8;border-radius:8px;padding:1em;background:#fff}
.cr-card.red{border-left:4px solid #E4162B;background:#fafafa}
.cr-card h4{margin-bottom:.3em}.cr-card p{margin:0;font-size:.95em}
.cr-hero{display:grid;grid-template-columns:1fr 1.1fr;gap:2em;align-items:center}
.cr-tiles{display:grid;grid-template-columns:1fr 1fr;grid-template-rows:1fr 1fr;gap:6px;height:26em}
.cr-tile{position:relative;display:block;overflow:hidden;border-radius:8px;background:#18181b}
.cr-tile.tall{grid-row:span 2}
.cr-tile img,.cr-gal img,.cr-photo img{position:absolute;inset:0;width:100%;height:100%;object-fit:cover;max-width:none}
.cr-tile span{position:absolute;left:0;right:0;bottom:0;padding:2em .8em .5em;background:linear-gradient(to top,rgba(0,0,0,.8),transparent);color:#fff;font-weight:700;font-size:.9em}
.cr-gallery{display:grid;grid-template-columns:repeat(6,1fr);gap:6px}
.cr-gal{position:relative;overflow:hidden;border-radius:8px;background:#f4f4f5;height:14em;grid-column:span 2}
.cr-s3{grid-column:span 3}.cr-s4{grid-column:span 4}.cr-s6{grid-column:span 6}
.cr-photos{display:grid;grid-template-columns:repeat(3,1fr);gap:6px}
.cr-photo{position:relative;overflow:hidden;border-radius:8px;background:#f4f4f5;height:18em}
.cr-svc{display:grid;grid-template-columns:1fr 240px;gap:1.2em;margin:0 0 1em}
.cr-svc.solo{grid-template-columns:1fr}
.cr-svc img{width:100%;height:auto;border-radius:6px;margin:0 0 .5em;display:block}
.cr-video{position:relative;padding-bottom:56.25%;height:0;overflow:hidden;border-radius:8px;background:#f4f4f5;margin:0 0 1em}
.cr-video iframe{position:absolute;top:0;left:0;width:100%;height:100%;border:0}
.cr-dl{display:grid;grid-template-columns:9em 1fr;gap:.5em 1.2em;border:1px solid #d4d4d8;border-radius:8px;padding:1em}
.cr-dl dt{font-weight:700}.cr-dl dd{margin:0}
.cr-year{border-bottom:2px solid #E4162B;padding-bottom:.2em}
.cr-intro{display:grid;grid-template-columns:220px 1fr;gap:1.5em;align-items:center}
.cr-intro img{width:100%;height:auto;border-radius:8px;display:block}
.cr-post{border:1px solid #d4d4d8;border-radius:8px;padding:1em;box-shadow:0 1px 2px rgba(0,0,0,.05)}
.cr-post h3{font-size:1.1em;margin:.2em 0 .4em}.cr-post h3 a{text-decoration:none}.cr-post h3 a:hover{text-decoration:underline}
.cr-date{font-size:.8em;margin:0!important}
.cr-excerpt{max-height:8.5em;overflow:hidden;font-size:.95em;position:relative}
.cr-excerpt:after{content:"";position:absolute;left:0;right:0;bottom:0;height:2.5em;background:linear-gradient(to top,#fff,rgba(255,255,255,0))}
.cr-excerpt img,.cr-excerpt iframe,.cr-excerpt table{display:none}
.cr-more{font-weight:700}
.cr-art{max-width:760px}.cr-art img,.cr-art iframe,.cr-art table{max-width:100%}.cr-art img{height:auto}
.cr-art .cr-date{margin:0 0 1em!important}
.cr-pager{display:flex;justify-content:space-between;gap:1em;margin-top:2em;font-weight:700}
.cr-foot{border-top:4px solid #E4162B;padding:24px 16px;font-size:.9em;text-align:center}
.cr-foot p{margin:0 0 .5em}
@media(max-width:700px){
.cr-hero,.cr-svc,.cr-photos,.cr-grid2,.cr-dl,.cr-intro{grid-template-columns:1fr}
.cr-tiles{height:22em}
.cr-gallery{grid-template-columns:repeat(2,1fr)}
.cr-gal,.cr-s3,.cr-s4,.cr-s6{grid-column:span 1;height:11em}
.cr-gal.cr-full{grid-column:span 2}
.cr h1{font-size:2em}.cr h2{font-size:1.6em}
.cr-main{padding-top:24px}
}
